Script:
Payments = { 
    paymentTypes: [
        { id: 1, name: "[resource_displayname[Statement]]" },
        { id: 2, name: "[resource_displayname[PayerPaymentAdvice]]" },
        { id: 3, name: "[resource_displayname[PayeePaymentAdvice]]" }
    ],
    states: [script[TransactionStates]],

    init: async function(app, container) {
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [ 
                    [meta[B2B/RemittanceAdvice]],
                    [meta[B2B/Company]]
                    ]
            }
        ]);

        var config = {
            endpoint: "B2B/RemittanceAdvice/FromSystem(systemId='" + app.Config.B2B.SourceSystem + "')", 
            odataAppend: "?$expand=Companies,References",
            computeFields: function(item) {
                item.CreditorReference = item.Companies.filter(c => c.Perspective == "Creditor")[0].CompanyReferenceId.split("|")[1];
            },
            customFields: [
                {
                    type: "array",
                    arrayField: "Companies",
                    fieldAppend: " and c/Perspective eq 'Creditor'",
                    field: "c/CompanyReference/Value",
                    templateField: "CreditorReference"
                }
            ]
        };
        var paymentDataSource = await model.getDatasource(config);
        await (await [script[PaymentGrid]]({element: container, dataSource: paymentDataSource})).init();
        $("[name=exportPaymentLines]", container).on("click", (e) => {
            e.preventDefault();
            var exportURL = api.apiRoot + "B2B/RemittanceAdviceLine/FromSystem(systemId='" + app.Config.B2B.SourceSystem + "')?$expand=InvoiceReference($select=Invoice;$expand=Invoice($select=Number)),CreditReference($select=Credit;$expand=Credit($select=Number)),RemittanceAdvice($select=CreditorName,CurrencyId,DueDate,DebtorPaymentDate)&$select=InvoiceReference,CreditReference,PaymentReference,LinePrice,RemittanceAdvice";
            var exportDialog = new ExportDialog({
                title: "[resource_displayname[exportpaymentlines]]",
                exportURL: exportURL
            });
            exportDialog.init();
        });
    }
};
